             }

-            const options = {
-              hostname: 'console.neon.tech',
-              path: '/api/v2/projects/' + projectId + '/branches',
-              headers: { 'Authorization': 'Bearer ' + apiKey }
-            };
-
-            https.get(options, (res) => {
-              let data = '';
-              res.on('data', chunk => data += chunk);
-              res.on('end', async () => {
-                if (res.statusCode !== 200) {
-                  console.log('Failed to list branches:', res.statusCode);
-                  return;
-                }
-                const branches = JSON.parse(data).branches || [];
-                const testBranches = branches.filter(b =>
-                  b.name.startsWith('test-') &&
-                  !b.protected &&
-                  !b.default
-                );
-                console.log('Found', testBranches.length, 'test branches to clean up');
-
-                for (const branch of testBranches) {
-                  const deleteOptions = {
-                    hostname: 'console.neon.tech',
-                    path: '/api/v2/projects/' + projectId + '/branches/' + branch.id,
-                    method: 'DELETE',
-                    headers: { 'Authorization': 'Bearer ' + apiKey }
-                  };
-
-                  await new Promise((resolve) => {
-                    const req = https.request(deleteOptions, (res) => {
-                      if (res.statusCode === 200 || res.statusCode === 204) {
-                        console.log('Deleted:', branch.name);
-                      } else {
-                        console.log('Failed to delete', branch.name, ':', res.statusCode);
-                      }
-                      resolve();
-                    });
-                    req.on('error', (e) => {
-                      console.log('Error deleting', branch.name, ':', e.message);
-                      resolve();
-                    });
-                    req.end();
-                  });
-                }
+            // Safety timeout — exit after 2 minutes regardless
+            const safetyTimer = setTimeout(() => {
+              console.log('Cleanup timed out after 2 minutes, exiting');
+              process.exit(0);
+            }, 120000);
+            safetyTimer.unref();
+
+            function apiRequest(options) {
+              return new Promise((resolve, reject) => {
+                const req = https.request(options, (res) => {
+                  let data = '';
+                  res.on('data', chunk => data += chunk);
+                  res.on('end', () => resolve({ statusCode: res.statusCode, data }));
+                });
+                req.on('error', reject);
+                req.end();
+              });
+            }
+
+            async function main() {
+              // List all branches
+              const listRes = await apiRequest({
+                hostname: 'console.neon.tech',
+                path: '/api/v2/projects/' + projectId + '/branches',
+                headers: { 'Authorization': 'Bearer ' + apiKey }
               });
-            }).on('error', (e) => {
-              console.log('Error listing branches:', e.message);
-            });
+
+              if (listRes.statusCode !== 200) {
+                console.log('Failed to list branches:', listRes.statusCode);
+                return;
+              }
+
+              const branches = JSON.parse(listRes.data).branches || [];
+              const testBranches = branches.filter(b =>
+                b.name.startsWith('test-') &&
+                !b.protected &&
+                !b.default
+              );
+              console.log('Found', testBranches.length, 'test branches to clean up');
+
+              // Delete branches in parallel (max 4 concurrent)
+              const concurrency = 4;
+              for (let i = 0; i < testBranches.length; i += concurrency) {
+                const batch = testBranches.slice(i, i + concurrency);
+                await Promise.all(batch.map(async (branch) => {
+                  try {
+                    const res = await apiRequest({
+                      hostname: 'console.neon.tech',
+                      path: '/api/v2/projects/' + projectId + '/branches/' + branch.id,
+                      method: 'DELETE',
+                      headers: { 'Authorization': 'Bearer ' + apiKey }
+                    });
+                    if (res.statusCode === 200 || res.statusCode === 204) {
+                      console.log('Deleted:', branch.name);
+                    } else {
+                      console.log('Failed to delete', branch.name, ':', res.statusCode);
+                    }
+                  } catch (e) {
+                    console.log('Error deleting', branch.name, ':', e.message);
+                  }
+                }));
+              }
+            }
+
+            main()
+              .then(() => { console.log('Cleanup complete'); process.exit(0); })
+              .catch((e) => { console.log('Cleanup error:', e.message); process.exit(0); });
           "

